-- Independent clinic identity: never infer or merge from doctors.clinic_name.
CREATE TABLE clinics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(btrim(name))>0), city text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE doctors ADD COLUMN clinic_id uuid REFERENCES clinics(id) ON DELETE SET NULL;
CREATE INDEX doctors_clinic_id_idx ON doctors(clinic_id);
CREATE TABLE forecast_months (month date PRIMARY KEY CHECK(EXTRACT(day FROM month)=1), closed_at timestamptz, closed_by uuid REFERENCES users(id));
CREATE TABLE forecast_late_exceptions (rep_id uuid NOT NULL REFERENCES users(id), month date NOT NULL REFERENCES forecast_months(month), allowed_by uuid NOT NULL REFERENCES users(id), allowed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(rep_id,month));
CREATE TABLE forecast_prices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), month date NOT NULL REFERENCES forecast_months(month), clinic_id uuid NOT NULL REFERENCES clinics(id), product_id uuid NOT NULL REFERENCES products(id), price numeric(14,2) NOT NULL CHECK(price>0), set_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(month,clinic_id,product_id));
CREATE TABLE forecast_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rep_id uuid NOT NULL REFERENCES users(id), month date NOT NULL REFERENCES forecast_months(month), version integer NOT NULL CHECK(version>0), status text NOT NULL CHECK(status IN ('draft','pending','approved','rejected','change_requested')), submitted_at timestamptz, reviewed_at timestamptz, reviewer_id uuid REFERENCES users(id), reason text, review_note text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(rep_id,month,version));
CREATE UNIQUE INDEX forecast_one_live_version ON forecast_versions(rep_id,month) WHERE status IN ('draft','pending','change_requested');
CREATE TABLE forecast_lines (version_id uuid NOT NULL REFERENCES forecast_versions(id), clinic_id uuid NOT NULL REFERENCES clinics(id), product_id uuid NOT NULL REFERENCES products(id), quantity integer NOT NULL CHECK(quantity>0), unit_price numeric(14,2) NOT NULL CHECK(unit_price>0), PRIMARY KEY(version_id,clinic_id,product_id));
CREATE TABLE forecast_targets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), month date NOT NULL REFERENCES forecast_months(month), rep_id uuid NOT NULL REFERENCES users(id), clinic_id uuid NOT NULL REFERENCES clinics(id), product_id uuid NOT NULL REFERENCES products(id), quantity integer NOT NULL CHECK(quantity>=0), unit_price numeric(14,2) NOT NULL CHECK(unit_price>0), set_by uuid NOT NULL REFERENCES users(id), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(month,rep_id,clinic_id,product_id));
CREATE TABLE forecast_sales (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), month date NOT NULL REFERENCES forecast_months(month), rep_id uuid NOT NULL REFERENCES users(id), clinic_id uuid NOT NULL REFERENCES clinics(id), product_id uuid NOT NULL REFERENCES products(id), quantity integer NOT NULL CHECK(quantity>0), unit_price numeric(14,2) NOT NULL CHECK(unit_price>0), status text NOT NULL CHECK(status IN ('pending','approved','rejected')), source_sale_id uuid REFERENCES forecast_sales(id), kind text NOT NULL DEFAULT 'sale' CHECK(kind IN ('sale','adjustment','return')), direction smallint NOT NULL DEFAULT 1 CHECK(direction IN (-1,1)), reason text, submitted_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz, reviewer_id uuid REFERENCES users(id), review_note text);
CREATE INDEX forecast_sales_month_rep ON forecast_sales(month,rep_id,status);
CREATE TABLE forecast_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), month date NOT NULL REFERENCES forecast_months(month), actor_id uuid NOT NULL REFERENCES users(id), entity text NOT NULL, entity_id uuid, action text NOT NULL, details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
